    intro: [],
    sections: [{"heading": "Giriş", "paragraphs": ["Su kaydırakları, yoğun kullanıma maruz kalan mühendislik yapılarıdır. Düzenli bakım; güvenliği artırır, arıza riskini azaltır ve yatırımın kullanım ömrünü uzatır."]}, {"heading": "Neden Bakım Yapılmalıdır?", "paragraphs": ["Periyodik bakım sayesinde yüzey deformasyonları, bağlantı gevşemeleri ve mekanik problemler erken tespit edilerek daha büyük maliyetlerin önüne geçilebilir."]}, {"heading": "Günlük Kontroller", "paragraphs": ["Kayma yüzeyleri, su akışı, bağlantı noktaları, iniş havuzu, merdivenler ve platformlar işletmeye açılmadan önce görsel olarak kontrol edilmelidir."]}, {"heading": "Periyodik Bakımlar", "paragraphs": ["Flanş bağlantıları, cıvatalar, destek konstrüksiyonları, conta sistemleri ve su dağıtım ekipmanları belirli aralıklarla detaylı şekilde incelenmelidir."]}, {"heading": "Fiberglas Yüzey Bakımı", "paragraphs": ["Yüzeyler uygun temizlik ürünleriyle temizlenmeli, UV etkisi ve aşınma belirtileri takip edilmeli, gerekli durumlarda profesyonel yüzey yenileme işlemleri uygulanmalıdır."]}, {"heading": "Güvenlik Kontrolleri", "paragraphs": ["Kaydırakların güvenlik işaretleri, korkulukları, platformları ve kullanıcı yönlendirmeleri düzenli olarak gözden geçirilmelidir."]}, {"heading": "Bakım Kayıtları", "paragraphs": ["Yapılan tüm bakım ve kontroller kayıt altına alınmalı; tarih, işlem ve sorumlu personel bilgileri düzenli şekilde dokümante edilmelidir."]}, {"heading": "Sonuç", "paragraphs": ["Planlı bakım uygulamaları, su kaydıraklarının güvenliğini artırırken işletme maliyetlerini azaltır ve tesisin uzun yıllar yüksek performansla hizmet vermesini sağlar."]}],
    faqs: [{"question": "Su kaydıraklarının bakımı ne sıklıkla yapılmalıdır?", "answer": "Günlük görsel kontrollerin yanında üretici tavsiyelerine uygun periyodik bakım programı uygulanmalıdır."}, {"question": "Fiberglas yüzeyler özel bakım ister mi?", "answer": "Evet. Uygun temizlik yöntemleri ve düzenli yüzey kontrolleri ürün ömrünü uzatır."}, {"question": "Bakım kayıtları neden önemlidir?", "answer": "İşletme güvenliği, izlenebilirlik ve planlı bakım yönetimi açısından kritik öneme sahiptir."}],
