import { BLOG_TRANSLATIONS } from './blogTranslations';

/**
 * Returns a blog object localized to the requested language.
 * Falls back gracefully to English or Turkish if a translation is missing.
 */
export function getLocalizedBlog(blog, lang = 'tr') {
  if (!blog) return null;
  const langKey = (lang || 'tr').toLowerCase().split('-')[0];
  if (langKey === 'tr') {
    return blog;
  }
  const trans = BLOG_TRANSLATIONS[blog.id]?.[langKey] || BLOG_TRANSLATIONS[blog.id]?.['en'];
  if (!trans) {
    return blog;
  }
  return {
    ...blog,
    title: trans.title || blog.title,
    description: trans.description || blog.description,
    focusKeyword: trans.focusKeyword !== undefined ? trans.focusKeyword : blog.focusKeyword,
    seoTitle: trans.seoTitle || blog.seoTitle,
    metaDesc: trans.metaDesc || blog.metaDesc,
    intro: trans.intro || blog.intro,
    sections: trans.sections || blog.sections,
    faqs: trans.faqs || blog.faqs,
  };
}

/**
 * Returns all blogs localized to the requested language.
 */
export function getLocalizedBlogs(lang = 'tr') {
  return BLOG_DATA.map((blog) => getLocalizedBlog(blog, lang));
}
